"""Generate the small Telly Sans bitmap subset (Pillow; input DejaVu Sans TTF)."""

import argparse
import math
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

CODEPOINTS = (
    list(range(32, 127))
    + list(range(0x400, 0x460))
    + [0xB0, 0x2013, 0x2014, 0x2018, 0x2019, 0x201C, 0x201D, 0x2026]
)


def generate(font_path, output):
    font = ImageFont.truetype(str(font_path), 16)
    lines = [
        "// Generated by scripts/generate_display_font.py; Telly Sans 16.",
        "// Derived from DejaVu Sans; see fonts/LICENSE_DEJAVU.txt.",
        "#pragma once",
        "struct TellyGlyph { uint32_t codepoint; uint8_t advance; uint8_t bitmap[50]; };",
        "static const TellyGlyph tellyGlyphs[] = {",
    ]
    for cp in sorted(CODEPOINTS):
        image = Image.new("L", (20, 20))
        ImageDraw.Draw(image).text((0, 16), chr(cp), font=font, fill=255, anchor="ls")
        pixels = [int(v >= 96) for v in image.getdata()]
        packed = [sum(pixels[n + b] << (7 - b) for b in range(8)) for n in range(0, 400, 8)]
        advance = math.ceil(font.getlength(chr(cp)))
        lines.append(
            "    {0x%04X, %d, {%s}}," % (cp, advance, ",".join("0x%02x" % b for b in packed))
        )
    lines.append("};")
    Path(output).write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("font", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    generate(args.font, args.output)
